:root {
  --sky: #e8f4fd;
  --horizon: #f9a825;
  --horizon-dark: #e65100;
  --text-dark: #1a237e;
  --text-mid: #37474f;
  --text-light: #78909c;
  --badge-bg: #c8e6c9;
  --badge-text: #2e7d32;
  --divider: #bbdefb;
  --white: #ffffff;
}

.voucher {
  background-color: var(--white);
  border: 2px solid var(--divider);
  border-radius: 16px;
  width: 400px;
  overflow: hidden;
  margin: 20px auto;
}

.voucher-header {
  background-color: var(--sky);
  border-bottom: 2px dashed var(--divider);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
}

.balloon-icon {
  font-size: 36px;
  line-height: 1;
}

.header-text {
  flex: 1;
}

.voucher-title {
  font-size: 20px;
  font-weight: 800;
  color: var(--text-dark);
  margin: 0;
  line-height: 1.2;
}

.voucher-subtitle {
  font-size: 13px;
  color: var(--horizon-dark);
  margin: 2px 0 0 0;
  font-weight: 600;
}

.voucher-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  border-radius: 6px;
  padding: 4px 8px;
  letter-spacing: 0.5px;
}

.voucher-body {
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.detail-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--divider);
  padding-bottom: 10px;
}

.detail-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.detail-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-light);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.detail-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-mid);
}
